# ============================================================================
# 19_phenomenological_data.R
#
# Fits of the mechanistic model to data that were NOT generated by a foraging
# process. The counts are drawn from the conventional statistical models,
# binomial and beta-binomial, around a fixed mean functional response
#   mu(x) = x [1 - exp(-f(x) T / x)],   f(x) = a x^z / (1 + a h x^z),
# with a type II (z = 1) or type III (z = 2) mean. The question is how well
# the mechanistic model reproduces the mean response and the distribution of
# the counts when the data have the form that conventional analyses assume.
#
# Design: z {1, 2} x distribution {binomial; beta-binomial with rho = 0.1 and
# rho = 0.3} (rho is the intra-class correlation: the variance is that of the
# binomial times 1 + (x - 1) rho); large design (8 densities, 64 trials);
# a and h as in the base scenario of the simulation study (h/T = 0.025, 20
# expected encounters per trial at the geometric mean density); 8 datasets
# per scenario; exploratory preset followed by verify_fit() (48 fits).
#
# Measures for each dataset:
#   * goodness of fit: AIC of the mechanistic model minus the AIC of the
#     generating model fitted by maximum likelihood (binomial or
#     beta-binomial, same mean function); the NLL of the mechanistic model
#     is the precise NLL (5 x 20,000 simulated trials per density);
#   * mean response: relative error of the simulated mean at the estimates
#     with respect to the true mean, over the densities;
#   * distribution of the counts: ratio of the predicted to the true variance
#     at each density, and total variation distance between the simulated
#     distribution at the estimates and the true distribution (0 = identical,
#     1 = no overlap); the same distance for the fitted generating model is
#     the benchmark;
#   * parameters: z, its 95% interval (coverage of the z of the mean), and h.
#
# Usage, from the root of the package repository with funresMech installed:
#   QUICK <- TRUE;  source("validation/R/19_phenomenological_data.R")  # check, ~5 min
#   rm(list = ls()); source("validation/R/19_phenomenological_data.R")   # complete run
# The complete run needs about 40 core-hours (about 2 to 3 h on 23 cores). It
# can be interrupted and resumed. Results:
# validation/tables/phenomenological_fits.csv and phenomenological_summary.csv.
# ============================================================================

library(funresMech)
stopifnot(packageVersion("funresMech") >= "1.1.0.9000")
source(file.path("validation", "R", "helpers.R"))

if (!exists("QUICK")) QUICK <- FALSE
WORKERS <- if (QUICK) 2L else max(1L, parallel::detectCores() - 1L)
DIR_RES <- file.path("validation", "results", if (QUICK) "phenomenological_quick" else "phenomenological")
DIR_TAB <- file.path("validation", "tables")
dir.create(DIR_RES, recursive = TRUE, showWarnings = FALSE); dir.create(DIR_TAB, showWarnings = FALSE)
SUFFIX <- if (QUICK) "_quick" else ""
GRID <- if (QUICK) c(0.5, 1, 2, 3) else seq(0.5, 5, by = 0.5)
N_PRECISE <- if (QUICK) 2000L else 20000L
N_PRED <- if (QUICK) 2000L else 20000L          # simulated trials per density for the predicted distribution

control_for <- function(preset, ...) {
  if (QUICK) funres_control(preset, n_sim = 200, itermax = 5, NP = 12, n_reeval = 2, ...)
  else funres_control(preset, ...)
}

# ---- scenarios -------------------------------------------------------------------
SCEN <- expand.grid(z = c(1, 2), rho = c(0, 0.1, 0.3))
SCEN$distribution <- ifelse(SCEN$rho == 0, "binomial", "beta-binomial")
SCEN$design <- "large"; SCEN$h_over_T <- 0.025; SCEN$E <- 20
SCEN$id <- sprintf("phenomenological_%s_z%g_rho%g_hT%g_E%g_large", sub("-", "", SCEN$distribution),
                   SCEN$z, SCEN$rho, SCEN$h_over_T, SCEN$E)
if (QUICK) SCEN <- SCEN[c(2, 6), ]

mean_parameters <- function(e) {
  dens <- DESIGNS[[e$design]]
  x_ref <- exp(mean(log(unique(dens))))
  c(a = e$E / (T_EXP * x_ref^e$z), h = e$h_over_T * T_EXP, z = e$z)
}
true_mean <- function(e, x) {
  p <- mean_parameters(e)
  funresMech:::.mu_parasitoid(x, p[["a"]], p[["h"]], p[["z"]], T_EXP)
}
# True probability of each count 0..x at density x
true_pmf <- function(e, x) {
  pr <- true_mean(e, x) / x
  if (e$rho == 0) return(stats::dbinom(0:x, x, pr))
  sh <- funresMech:::.bb_shapes(pr, e$rho)
  exp(funresMech:::.dbbinom_log(0:x, x, sh$alpha, sh$beta))
}
simulate_phenomenological <- function(e, j) {
  dens <- DESIGNS[[e$design]]
  set.seed(data_seed(e$id, j))
  pr <- true_mean(e, dens) / dens
  p_i <- if (e$rho == 0) pr else {
    sh <- funresMech:::.bb_shapes(pr, e$rho)
    stats::rbeta(length(dens), sh$alpha, sh$beta)
  }
  data.frame(dens = dens, par = stats::rbinom(length(dens), dens, p_i))
}

# Maximum-likelihood fit of the generating model (binomial or beta-binomial)
# with the same mean function; time in units of T, as in the package.
fit_generating <- function(d, rho0) {
  if (rho0 > 0) {
    b <- funresMech:::.fit_bb_model(d, funres_model())
    return(list(nll = b$nll, n_par = b$n_par,
                par = c(a = b$par[["a_star"]] / T_EXP, h = b$par[["h_star"]] * T_EXP,
                        z = b$par[["z"]], rho = b$par[["rho"]])))
  }
  fn <- function(th) {
    mu <- funresMech:::.mu_parasitoid(d$dens, exp(th[1]), exp(th[2]), exp(th[3]), 1)
    ll <- stats::dbinom(d$par, d$dens, pmin(pmax(mu / d$dens, 1e-12), 1 - 1e-12), log = TRUE)
    if (any(!is.finite(ll))) 1e10 else -sum(ll)
  }
  lo <- c(log(1e-8), log(1e-6), log(0.1)); up <- c(log(1e4), log(1), log(20))
  de <- suppressWarnings(DEoptim::DEoptim(fn, lo, up, DEoptim::DEoptim.control(itermax = 150, NP = 40,
                                                                               trace = FALSE)))
  pol <- stats::optim(de$optim$bestmem, fn, method = "Nelder-Mead", control = list(maxit = 5000, reltol = 1e-12))
  th <- if (pol$value < de$optim$bestval) pol$par else de$optim$bestmem
  list(nll = min(pol$value, de$optim$bestval), n_par = 3L,
       par = c(a = exp(th[[1]]) / T_EXP, h = exp(th[[2]]) * T_EXP, z = exp(th[[3]]), rho = 0))
}
# Probability of each count under the fitted generating model
generating_pmf <- function(g, x) {
  pr <- funresMech:::.mu_parasitoid(x, g$par[["a"]], g$par[["h"]], g$par[["z"]], T_EXP) / x
  if (g$par[["rho"]] == 0) return(stats::dbinom(0:x, x, pr))
  sh <- funresMech:::.bb_shapes(pr, g$par[["rho"]])
  exp(funresMech:::.dbbinom_log(0:x, x, sh$alpha, sh$beta))
}

jobs <- do.call(rbind, lapply(SCEN$id, function(id)
  data.frame(arm = "phenomenological", scenario = id, dataset = seq_len(if (QUICK) 1 else 8),
             variant = "exploratory")))
jobs$file <- file.path(DIR_RES, sprintf("%s__%s__d%d.rds", jobs$arm, jobs$scenario, jobs$dataset))
pending <- jobs[!file.exists(jobs$file), ]
cat(sprintf("Fits: %d in total, %d pending; %d workers.\n", nrow(jobs), nrow(pending), WORKERS))

run_one <- function(job) {
  library(funresMech)
  future::plan(future::sequential)
  t0 <- proc.time()[["elapsed"]]
  e <- SCEN[SCEN$id == job$scenario, ]
  d <- simulate_phenomenological(e, job$dataset); m <- funres_model()
  set.seed(fit_seed("19", job$arm, job$scenario, job$dataset, job$variant))
  f <- suppressWarnings(fit_funres(d, T_EXP, m, z_grid = GRID, control = control_for(job$variant, bb = TRUE)))
  f <- verify_fit(f)
  res <- fit_row(f, e$z)
  res$nll_precise_hat <- precise_nll(f$par, m, d)
  g <- fit_generating(d, e$rho)
  res$nll_generating <- g$nll
  res$aic_mechanistic <- 2 * res$nll_precise_hat + 2 * f$n_par
  res$aic_generating <- 2 * g$nll + 2 * g$n_par
  res$dAIC_vs_generating <- res$aic_mechanistic - res$aic_generating   # positive: the generating model fits better
  res$nll_true <- -sum(vapply(seq_len(nrow(d)), function(i)
    log(true_pmf(e, d$dens[i])[d$par[i] + 1]), 0))
  # predicted distributions at the estimates, by density
  ux <- sort(unique(d$dens))
  sims <- simulate_response(m, dens = ux, T = T_EXP, par = f$par, n_sim = N_PRED)
  by_x <- do.call(rbind, lapply(ux, function(x) {
    v <- sims$response[sims$dens == x]
    p_sim <- tabulate(v + 1L, nbins = x + 1L) / length(v)
    p_true <- true_pmf(e, x); p_gen <- generating_pmf(g, x)
    k <- 0:x
    data.frame(dens = x, mean_true = sum(k * p_true), mean_mech = mean(v),
               var_true = sum(k^2 * p_true) - sum(k * p_true)^2, var_mech = stats::var(v),
               tv_mech = 0.5 * sum(abs(p_sim - p_true)), tv_generating = 0.5 * sum(abs(p_gen - p_true)))
  }))
  res$mean_rel_error <- mean(abs(by_x$mean_mech - by_x$mean_true) / by_x$mean_true)
  res$var_ratio_median <- stats::median(by_x$var_mech / by_x$var_true)
  res$tv_mech <- mean(by_x$tv_mech); res$tv_generating <- mean(by_x$tv_generating)
  res$z_generating <- g$par[["z"]]; res$rho_generating <- g$par[["rho"]]
  out <- list(job = job[, c("arm", "scenario", "dataset", "variant")], res = res, by_density = by_x,
              checks = checks_long(f), fit = lighten(f), generating = g,
              seconds = proc.time()[["elapsed"]] - t0)
  saveRDS(out, job$file)
  TRUE
}

run_jobs(pending, run_one,
         globals = mget(c("run_one", "pending", "SCEN", "DESIGNS", "T_EXP", "GRID", "N_PRECISE", "N_PRED",
                          "QUICK", "control_for", "mean_parameters", "true_mean", "true_pmf",
                          "simulate_phenomenological", "fit_generating", "generating_pmf",
                          "data_seed", "fit_seed", "SEEDS_DATA", "SEEDS_FIT", "precise_nll", "lighten",
                          "fit_row", "checks_long")),
         workers = WORKERS, log_file = file.path(DIR_RES, "errors.log"))

# ---- tables ------------------------------------------------------------------
O <- lapply(jobs$file[file.exists(jobs$file)], readRDS)
if (length(O)) {
  G <- do.call(rbind, lapply(O, function(o)
    data.frame(o$job, o$res, seconds = o$seconds,
               SCEN[SCEN$id == o$job$scenario, c("z", "rho", "distribution", "h_over_T", "E", "design")],
               row.names = NULL)))
  G$h_ratio <- G$h_hat / (G$h_over_T * T_EXP)
  G$z_error <- G$z_hat - G$z
  G$open <- G$low_open | G$high_open
  write.csv(G, file.path(DIR_TAB, paste0("phenomenological_fits", SUFFIX, ".csv")), row.names = FALSE)
  B <- do.call(rbind, lapply(O, function(o) data.frame(o$job[, c("scenario", "dataset")], o$by_density,
                                                       row.names = NULL)))
  write.csv(B, file.path(DIR_TAB, paste0("phenomenological_by_density", SUFFIX, ".csv")), row.names = FALSE)

  S <- do.call(rbind, lapply(split(G, G$scenario), function(g) {
    w <- wilson(g$covers)
    data.frame(distribution = g$distribution[1], z = g$z[1], rho = g$rho[1], n = nrow(g),
               median_dAIC_vs_generating = stats::median(g$dAIC_vs_generating),
               pct_mechanistic_within_2_AIC = 100 * mean(g$dAIC_vs_generating <= 2),
               median_mean_rel_error = stats::median(g$mean_rel_error),
               median_var_ratio = stats::median(g$var_ratio_median),
               median_tv_mechanistic = stats::median(g$tv_mech),
               median_tv_generating = stats::median(g$tv_generating),
               coverage_z = w[["p"]], coverage_low = w[["lower"]], coverage_high = w[["upper"]],
               median_z_error = stats::median(g$z_error), median_h_ratio = stats::median(g$h_ratio),
               excludes_1 = mean(g$excludes_1), open_interval = mean(g$open),
               median_hours = stats::median(g$seconds) / 3600)
  }))
  write.csv(S, file.path(DIR_TAB, paste0("phenomenological_summary", SUFFIX, ".csv")), row.names = FALSE)
  rownames(S) <- NULL
  print(S[, c("distribution", "z", "rho", "n", "median_dAIC_vs_generating", "median_mean_rel_error",
              "median_var_ratio", "median_tv_mechanistic", "median_tv_generating", "coverage_z")], digits = 3)
}
